# Databricks notebook source
# Step 8: outcome feedback. Reads investigator decisions from Lakebase and measures precision.
#
# The workbench writes each triage decision to Lakebase (ipw.case_outcome). This step copies those
# decisions into Unity Catalog (silver_investigation_outcome, MERGE on outcome_id) and rebuilds
# gold_precision: escalated and cleared counts, and precision, by primary signal, risk band and
# week, from the synthetic history and the live decisions together.
#
# Authentication: a short-lived Lakebase database credential generated by the SDK for the job's
# identity. Nothing is stored. If the Lakebase endpoint or the outcome table does not exist yet
# (the workbench has not been deployed), the silver table stays empty, gold_precision is rebuilt from
# history alone, and the step exits cleanly. Connection failures are not swallowed.

# COMMAND ----------

# MAGIC %pip install "psycopg[binary]"

# COMMAND ----------

import os
import sys

dbutils.widgets.text("src_dir", "")
dbutils.widgets.text("lakebase_project_id", "")
dbutils.widgets.text("lakebase_branch_id", "production")
dbutils.widgets.text("lakebase_endpoint_id", "primary")
_src = dbutils.widgets.get("src_dir").strip()
_src_dir = next((c for c in [_src, os.path.join(_src, "src"), "."] if c and os.path.isfile(os.path.join(c, "common.py"))), None)
if _src_dir is None:
    raise FileNotFoundError("common.py not found - pass src_dir pointing at the use case's src folder")
sys.path.insert(0, _src_dir)

import datetime as dt  # noqa: E402

import pandas as pd  # noqa: E402

import reporting  # noqa: E402
from common import fq, get_params, sql_literal, write_empty, write_table  # noqa: E402

params = get_params({"catalog": "", "schema": ""}, dbutils)
CATALOG, SCHEMA = params["catalog"], params["schema"]
PROJECT = dbutils.widgets.get("lakebase_project_id").strip()
BRANCH = dbutils.widgets.get("lakebase_branch_id").strip()
ENDPOINT = dbutils.widgets.get("lakebase_endpoint_id").strip()
DATABASE = "databricks_postgres"        # the project's default database
OUTCOME_SCHEMA, OUTCOME_TABLE = "ipw", "case_outcome"
if not CATALOG or not SCHEMA or not PROJECT:
    raise ValueError("catalog, schema and lakebase_project_id parameters are required")
t = lambda name: fq(CATALOG, SCHEMA, name)  # noqa: E731

SILVER = t("silver_investigation_outcome")
SILVER_DDL = (
    "outcome_id STRING, case_id STRING, outcome STRING, reason_code STRING, notes STRING, "
    "risk_score INT, risk_band STRING, primary_signal STRING, decided_by STRING, decided_at TIMESTAMP, "
    "synced_ts TIMESTAMP"
)
LIVE_COLUMNS = ["outcome_id", "case_id", "outcome", "reason_code", "notes", "risk_score", "risk_band",
                "primary_signal", "decided_by", "decided_at"]

# COMMAND ----------

write_empty(spark, SILVER, SILVER_DDL,
            "Investigator decisions copied from the Lakebase workbench. Synthetic pipeline output: decisions recorded in the workbench, not findings.")

def fetch_live_outcomes():
    """Return (DataFrame of decisions, None) or (None, reason) when there is nothing to read yet."""
    import psycopg
    from databricks.sdk import WorkspaceClient
    from databricks.sdk.errors import NotFound

    w = WorkspaceClient()
    endpoint_name = f"projects/{PROJECT}/branches/{BRANCH}/endpoints/{ENDPOINT}"
    try:
        endpoint = w.postgres.get_endpoint(name=endpoint_name)
    except NotFound:
        return None, f"Lakebase endpoint {endpoint_name} not found; workbench not deployed yet"
    host = getattr(getattr(endpoint, "status", None), "hosts", None)
    host = getattr(host, "host", None)
    if not host:
        raise RuntimeError(f"could not resolve a host for {endpoint_name}")
    credential = w.postgres.generate_database_credential(endpoint=endpoint_name)
    user = w.current_user.me().user_name

    with psycopg.connect(host=host, port=5432, dbname=DATABASE, user=user, password=credential.token,
                         sslmode="require", connect_timeout=30) as conn:
        exists = conn.execute("SELECT to_regclass(%s)", (f"{OUTCOME_SCHEMA}.{OUTCOME_TABLE}",)).fetchone()[0]
        if exists is None:
            return None, f"{OUTCOME_SCHEMA}.{OUTCOME_TABLE} does not exist yet"
        cols = ", ".join(c if c != "outcome_id" else "outcome_id::text AS outcome_id" for c in LIVE_COLUMNS)
        rows = conn.execute(f"SELECT {cols} FROM {OUTCOME_SCHEMA}.{OUTCOME_TABLE}").fetchall()
    frame = pd.DataFrame(rows, columns=LIVE_COLUMNS)
    frame["decided_at"] = pd.to_datetime(frame["decided_at"], utc=True).dt.tz_convert(None)
    return frame, None

live, reason = fetch_live_outcomes()
if reason:
    print(f"No live outcomes read: {reason}. Silver table left as is; gold_precision uses history only.")
else:
    print(f"live decisions read from Lakebase: {len(live)}")

# COMMAND ----------

if live is not None and len(live):
    live = live.copy()
    live["synced_ts"] = dt.datetime.now(dt.timezone.utc).replace(tzinfo=None)
    stage = spark.createDataFrame(
        live.astype(object).where(pd.notna(live), None),
        schema=f"{SILVER_DDL}",
    )
    stage.createOrReplaceTempView("ipw_outcome_stage")
    spark.sql(f"""
        MERGE INTO {SILVER} AS target
        USING ipw_outcome_stage AS source
        ON target.outcome_id = source.outcome_id
        WHEN MATCHED THEN UPDATE SET *
        WHEN NOT MATCHED THEN INSERT *
    """)
    print(f"merged {len(live)} decisions into {SILVER}")

# COMMAND ----------

history = spark.table(t("gold_outcome_history")).toPandas()
history = history[["primary_signal", "risk_band", "outcome", "decided_ts"]]
live_all = spark.table(SILVER).selectExpr("primary_signal", "risk_band", "outcome", "decided_at AS decided_ts").toPandas()
precision = reporting.precision_table(pd.concat([history, live_all], ignore_index=True))

GOLD_PRECISION_DDL = ("primary_signal STRING, risk_band STRING, week DATE, escalated INT, cleared INT, "
                      "precision DOUBLE")
GOLD_PRECISION_COMMENT = ("SYNTHETIC-HISTORY-AND-LIVE precision by primary signal, risk band and week: escalated "
                          "versus cleared decisions. Indicates how often flags survive triage; not a measure of "
                          "real-world accuracy.")
if len(precision):
    write_table(spark, precision, t("gold_precision"), GOLD_PRECISION_COMMENT)
else:
    spark.sql(f"CREATE OR REPLACE TABLE {t('gold_precision')} ({GOLD_PRECISION_DDL}) COMMENT {sql_literal(GOLD_PRECISION_COMMENT)}")
print(f"gold_precision rows: {len(precision)}")
